div.script:
document.addEventListener('DOMContentLoaded', function () {
    var btn = document.getElementById('prospire_coupon_apply');
    if (!btn) { return; }
    btn.addEventListener('click', function () {
        var input = document.getElementById('prospire_coupon_input');
        var errBox = document.getElementById('prospire_coupon_error');
        errBox.style.display = 'none';
        fetch('/slides/coupon_join', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params: {
                    channel_id: parseInt(btn.getAttribute('data-channel-id'), 10),
                    coupon: input.value
                }
            })
        }).then(function (response) { return response.json(); })
          .then(function (resp) {
              var result = resp.result || {};
              if (result.success) {
                  location.reload();
              } else {
                  errBox.textContent = result.error || 'Invalid coupon code';
                  errBox.style.display = 'block';
              }
          }).catch(function () {
              errBox.textContent = 'Something went wrong, please try again.';
              errBox.style.display = 'block';
          });
    });
});
